// B"H
// build-bundle.mjs — Geelooy OS CSS bundler (OS desktop fix, 2026-11-12).
//
// The OS index linked 24 stylesheets — 24 render-blocking requests on
// every OS boot, before first paint. This builder folds them into ONE
// file in exact cascade order, following browser @import semantics, the
// same way geelooy/heichelos/build-bundle.mjs does for the heichel
// shell: only @imports that lead their file are honored; a later
// @import is one browsers drop, so the builder drops it too and says
// so. No relative asset url()s exist anywhere in the closure (verified
// at build time — the builder aborts if one appears), so plain
// concatenation cannot break asset paths.
//
// Usage: node build-bundle.mjs   (run from geelooy/os)
// Output: os-bundle.css next to this script. The template pins it by
// content hash, so nginx serves it immutable. Sources stay on disk;
// edit them and re-run the builder.

import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const osDir = dirname(fileURLToPath(import.meta.url));
const geelooyDir = resolve(osDir, '..');
const outPath = join(osDir, 'os-bundle.css');

// The index.html links, frozen in cascade order. Since the bundle
// landed, the template links only os-bundle.css, so the builder
// carries the list itself. Order IS the cascade — do not reorder.
const links = [
	'./styles.css',
	'./civilization/styles.css',
	'./native-executable-accessibility.css',
	'./styles/revelation/tokens.css',
	'./styles/revelation/icon-language.css',
	'./styles/revelation/shell.css',
	'./styles/revelation/dock.css',
	'./styles/revelation/dock-pinned.css',
	'./styles/revelation/windows.css',
	'./styles/revelation/overlays.css',
	'./styles/revelation/command.css',
	'./styles/revelation/launcher.css',
	'./styles/revelation/launcher-records.css',
	'./styles/revelation/launcher-disclosures.css',
	'./styles/revelation/launcher-mobile.css',
	'./styles/revelation/feedback.css',
	'./styles/revelation/responsive.css',
	'./styles/revelation/responsive-mobile.css',
	'./styles/revelation/accessibility.css',
	'./styles/revelation/skip-link.css',
	'../style/revelation-v4/index.css',
	'./styles/revelation-v4.css',
	'/css/awp-polish.css',
	'./styles/revelation/law8-os-shell.css'
];

const warnings = [];
const seen = new Set();
const parts = [];
let abort = false;

function stripCommentsState(line, state) {
	let out = '';
	for (let i = 0; i < line.length; i++) {
		if (state.inComment) {
			if (line[i] === '*' && line[i + 1] === '/') { state.inComment = false; i++; out += '  '; } else out += ' ';
		} else if (line[i] === '/' && line[i + 1] === '*') {
			state.inComment = true; i++; out += '  ';
		} else out += line[i];
	}
	return out;
}

function expand(absPath) {
	const rel = relative(geelooyDir, absPath);
	if (seen.has(absPath)) { warnings.push(`duplicate skipped (already in cascade): ${rel}`); return; }
	seen.add(absPath);
	if (!existsSync(absPath)) { warnings.push(`MISSING @import target (browser 404s it, contributes nothing): ${rel}`); return; }
	const text = readFileSync(absPath, 'utf8');
	const state = { inComment: false };
	let leading = true;
	const body = [];
	for (const line of text.split('\n')) {
		const code = stripCommentsState(line, state);
		const imp = /^\s*@import\s+(?:url\(\s*)?["']?([^"')\s;]+)["']?\s*\)?\s*;?\s*$/.exec(code);
		if (imp && !state.inComment) {
			const target = imp[1].split('?')[0];
			if (/^https?:/.test(target)) { warnings.push(`external @import kept as-is (INVALID mid-bundle, must fix): ${rel} -> ${target}`); body.push(line); leading = false; continue; }
			if (!leading) { warnings.push(`late @import dropped (browsers drop it too): ${rel} -> ${target}`); continue; }
			const targetAbs = target.startsWith('/')
				? join(geelooyDir, target)
				: resolve(dirname(absPath), target);
			expand(targetAbs);
			continue;
		}
		if (/^\s*@charset\b/.test(code)) continue;
		const url = /url\(\s*["']?([^"')]+)["']?\s*\)/.exec(code);
		if (url && !/^(https?:|data:|#)/.test(url[1])) {
			warnings.push(`RELATIVE url() in ${rel}: ${url[1]} — concatenation would break it`);
			abort = true;
		}
		if (code.trim() && !/^\s*@/.test(code)) leading = false;
		body.push(line);
	}
	parts.push(`\n/* ==== ${rel} ==== */\n` + body.join('\n'));
}

for (const href of links) {
	const abs = href.startsWith('/')
		? join(geelooyDir, href.replace(/^\//, ''))
		: resolve(osDir, href);
	expand(abs);
}

if (abort) {
	console.log('ABORT: relative url() found — fix the sources first, do not write a broken bundle.');
	for (const w of warnings) console.log('WARN:', w);
	process.exit(1);
}

const banner = `@charset "UTF-8";\n/* B"H — GENERATED by os/build-bundle.mjs. Do not edit by hand.\n * One bundle for the Geelooy OS desktop, folded from ${seen.size} source sheets in exact\n * cascade order. Sources stay on disk; edit them and re-run the builder. */\n`;
writeFileSync(outPath, banner + parts.join('\n'));
console.log(`wrote ${relative(geelooyDir, outPath)} from ${seen.size} files, ${links.length} template links`);
for (const w of warnings) console.log('WARN:', w);
